question:
নিচের C প্রোগ্রামটির আউটপুট কী হবে তা স্টেপ-বাই-স্টেপ ট্রেস (Trace) করে ব্যাখ্যা করো:
```c
#include <stdio.h>
void fun(int *p, int *q) {
    p = q;
    *p = 20;
}
int main() {
    int a = 10, b = 15;
    fun(&a, &b);
    printf("a = %d, b = %d\n", a, b);
    return 0;
}
```

নিচের C কোডটির আউটপুট কী হবে এবং কেন?
```c
#include <stdio.h>
int main() {
    int arr[] = {10, 20, 30, 40, 50};
    int *ptr = arr;
    printf("%d, ", *ptr++);
    printf("%d, ", *++ptr);
    printf("%d, ", ++*ptr);
    printf("%d\n", (*ptr)++);
    return 0;
}
```

নিচের রিকার্সিভ (Recursive) ফাংশনটির আউটপুট কত হবে? রিকার্শন ট্রি (Recursion Tree) এঁকে দেখাও:
```c
#include <stdio.h>
void count(int n) {
    if (n <= 0) return;
    printf("%d ", n);
    count(n - 1);
    printf("%d ", n);
}
int main() {
    count(3);
    return 0;
}
```

নিচের প্রোগ্রামে `static` ভ্যারিয়েবলের ব্যবহার লক্ষ্য করে আউটপুট নির্ণয় করো:
```c
#include <stdio.h>
void display() {
    static int x = 5;
    int y = 5;
    x += 2;
    y += 2;
    printf("x = %d, y = %d\n", x, y);
}
int main() {
    display();
    display();
    display();
    return 0;
}
```

